import React, { useState } from "react";
import Navbar from "../components/Navbar";
import { api } from "../utils/api";

export default function Login() {
  const [loading, setLoading] = useState(false);

  const [form, setForm] = useState({
    email: "",
    password: ""
  });

  async function submit(e) {
    e.preventDefault();
    setLoading(true);

    try {
      const res = await api.post("/api/auth/login", form);

      localStorage.setItem("user_token", res.data.token);
      localStorage.setItem("user_profile", JSON.stringify(res.data.user));

      window.location.href = "/portal";
    } catch (err) {
      alert(err?.response?.data?.message || "Login failed");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <Navbar />

      <div className="max-w-lg mx-auto px-4 py-12">
        <h1 className="text-4xl font-black">User Login</h1>
        <p className="text-gray-600 mt-2">
          Login to see your tickets and SOC reply.
        </p>

        <form
          onSubmit={submit}
          className="mt-8 bg-white rounded-3xl shadow p-6 space-y-4"
        >
          <input
            className="w-full border rounded-2xl px-4 py-3"
            placeholder="Email"
            type="email"
            value={form.email}
            onChange={(e) => setForm({ ...form, email: e.target.value })}
          />

          <input
            className="w-full border rounded-2xl px-4 py-3"
            placeholder="Password"
            type="password"
            value={form.password}
            onChange={(e) => setForm({ ...form, password: e.target.value })}
          />

          <button
            disabled={loading}
            className="w-full px-6 py-3 rounded-2xl bg-gray-900 text-white font-semibold"
          >
            {loading ? "Logging in..." : "Login"}
          </button>

          <p className="text-sm text-gray-600 text-center">
            New user?{" "}
            <a href="/signup" className="text-blue-600 underline">
              Create account
            </a>
          </p>
        </form>
      </div>
    </div>
  );
}
